import { decryptSecret } from './lib/crypto-box';
import { db } from './lib/db';
import nodemailer from 'nodemailer';
import { ImapFlow } from 'imapflow';

(async () => {
  const i = await db.inbox.findFirstOrThrow();
  const smtpPass = decryptSecret(i.smtpPassEnc)!;
  const imapPass = decryptSecret(i.imapPassEnc)!;

  const marker = 'AUDIT-TEST-' + Date.now();
  const transport = nodemailer.createTransport({
    host: i.smtpHost, port: i.smtpPort, secure: false,
    requireTLS: true,
    auth: { user: i.smtpUser, pass: smtpPass },
    connectionTimeout: 10000,
  });

  console.log('Sending test message, marker=', marker);
  const info = await transport.sendMail({
    from: i.smtpUser,
    to: 'hello@trynxeon.com',
    subject: 'Relay audit test ' + marker,
    text: 'Live end-to-end audit test ' + marker,
  });
  console.log('SMTP accepted:', info.response);

  // poll IMAP for delivery
  const client = new ImapFlow({
    host: i.imapHost, port: i.imapPort, secure: true,
    tls: { servername: 'mail.nxeon.cloud' },
    auth: { user: i.imapUser, pass: imapPass },
    logger: false,
  });
  await client.connect();
  console.log('IMAP connected');
  let lock = await client.getMailboxLock('INBOX');
  let found = null;
  try {
    for (let attempt = 0; attempt < 10 && !found; attempt++) {
      const uids = await client.search({ subject: marker });
      if (uids && uids.length) {
        for await (let msg of client.fetch(uids, { envelope: true, source: true })) {
          found = msg;
        }
      }
      if (!found) { await new Promise(r => setTimeout(r, 3000)); }
    }
  } finally {
    lock.release();
  }
  if (!found) {
    console.log('NOT FOUND after polling — delivery may have failed or is delayed');
  } else {
    const src = found.source.toString('utf8');
    const headerBlock = src.split(/\r?\n\r?\n/)[0];
    console.log('=== FOUND MESSAGE HEADERS ===');
    for (const line of headerBlock.split(/\r?\n/)) {
      if (/^(Authentication-Results|Received-SPF|DKIM-Signature|From|To|Subject|Received:)/i.test(line)) {
        console.log(line);
      }
    }
  }
  await client.logout();
  process.exit(0);
})().catch(e => { console.error('ERROR', e); process.exit(1); });
