 * Load the platform SMTP settings the same way lib/mailer.ts does — the same
 * Setting rows (smtp_host/port/user/pass/secure), the same encrypted-password
 * tolerance, the same env fallback. Loaded lazily so importing this module never
 * touches the DB (keeps the module unit-testable and side-effect-free).
 */
async function loadSmtpConfig(): Promise<SmtpConfig> {
  const { db } = await import("@/lib/db");
  const { decryptSecret } = await import("@/lib/crypto-box");
  const rows = await db.setting.findMany({
    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_secure"] } },
  });
  const s = Object.fromEntries(rows.map((r) => [r.key, r.value])) as Record<string, string>;
  const storedPass = s.smtp_pass;
  const pass = storedPass ? decryptSecret(storedPass) ?? storedPass : process.env.SMTP_PASS || "";
  return {
    host: s.smtp_host || process.env.SMTP_HOST || "",
    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
    user: s.smtp_user || process.env.SMTP_USER || "",
    pass,
    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
  };
}

/**
 * Nxeon Mail (Mailcow) SMTP transport. The From identity is per-brand (passed on
 * each message) rather than the platform's transactional `smtp_from`, so a cold
 * campaign always sends as its dedicated sending identity — never as the platform.
 */
export class NxeonSmtpTransport implements MailTransport {
  readonly name = "nxeon-smtp";
  constructor(private readonly cfg: SmtpConfig) {}

  private transporter() {
    if (!this.cfg.host) {
      return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
    }
    const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
    return nodemailer.createTransport({
      host: this.cfg.host,
      port: this.cfg.port,
      secure: this.cfg.secure,
      auth: this.cfg.user ? { user: this.cfg.user, pass: this.cfg.pass } : undefined,
      ...(servername ? { tls: { servername } } : {}),
    });
  }

  async send(msg: RenderedMessage): Promise<SendResult> {
    const info = await this.transporter().sendMail({
      from: msg.from,
      to: msg.to,
      replyTo: msg.replyTo,
      subject: msg.subject,
      html: msg.html,
      text: msg.text,
      headers: msg.headers,
    });
    return { messageId: (info as { messageId?: string })?.messageId };
  }
}

/**
 * Amazon SES adapter SEAM. Left as a stub because SES is not provisioned yet and
 * this phase must not add dependencies or send anything. When a brand's domain
 * lives on SES, wire the AWS SDK here behind the same interface — the worker code
 * does not change.
 */
export class SesTransport implements MailTransport {
  readonly name = "ses";
  async send(_msg: RenderedMessage): Promise<SendResult> {
    throw new Error(
      "SES transport is not configured. The cold-email engine currently sends only via Nxeon Mail (SMTP). " +
        "Provision SES + wire the AWS SDK into SesTransport.send before selecting it.",
    );
  }
}

export type TransportKind = "nxeon-smtp" | "ses";

